create or replace function public.admin_conversion_dashboard(range_days integer default 30) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare d integer:=greatest(7,least(coalesce(range_days,30),90)); result jsonb; begin if auth.uid() is null or not private.has_role('admin'::public.user_role) then raise exception 'Admin access required'; end if; with cohort as (select u.created_at from auth.users u where u.created_at>=now()-make_interval(days=>d)), daily as (select jsonb_agg(jsonb_build_object('date',series.day::date,'accounts',coalesce(created.accounts,0)) order by series.day) value from generate_series(current_date-(d-1),current_date,interval '1 day') as series(day) left join (select created_at::date account_day,count(*) accounts from cohort group by created_at::date) created on created.account_day=series.day::date) select jsonb_build_object('daily_accounts',daily.value) into result from daily; return result; end; $$;
